parameters.jsCode:
// ¿HUBO UN CIERRE DE VENTA?
//
// La prueba NO es que el modelo diga que el pedido está confirmado. Eso lo
// escribe el modelo, o sea es una afirmación, no un hecho, y es el mismo modo
// de fallo que ya nos costó las citas duplicadas. La prueba de que el cliente
// pagó es que el CLIENTE MANDÓ UNA IMAGEN —el comprobante— y que sobre ese
// mensaje el asistente dio el pago por recibido.
//
// Las dos condiciones juntas dejan afuera exactamente lo que la oferta excluye:
// mandar el QR y que el cliente no pague (no hay imagen), y mandar información
// que nadie confirma.
//
// DE DÓNDE SALE CADA DATO, que es donde me equivoqué la primera vez:
// `Procesar respuesta` NO arrastra `tipo` ni `mensajeId`, y al texto del
// asistente lo llama `respuesta`, no `texto`. El tipo y el id del mensaje hay
// que ir a buscarlos al normalizador, con `.first()` y no `.item` —después de
// un nodo Code, `.item` puede no resolver.
const item = $json;
const entrada = $('Normalizar entrada').first().json;

// IMAGEN **O DOCUMENTO**. Lo encontramos probando: el cliente mandó el
// comprobante y WhatsApp lo clasificó como `document`, no como `image` —pasa
// con un PDF del banco y también cuando el teléfono adjunta la foto como
// archivo en vez de como imagen. Exigir `image` dejaba afuera la mitad de los
// comprobantes reales, y sin ningún error: todo verde y cero cierres.
//
// Se aceptan esos dos y NO los demás: un audio o un video no son un
// comprobante, y contarlos seria cobrar por algo que no ocurrio.
const COMPROBANTE = ['image', 'document'];
const esComprobanteDelCliente = COMPROBANTE.includes(entrada.tipo);
const confirmoElPago = /SIMULADO/i.test(String(item.respuesta ?? ''));
const referencia = String(entrada.mensajeId ?? '');

return [{ json: {
  ...item,
  hayCierre: Boolean(esComprobanteDelCliente && confirmoElPago && referencia),
  referenciaCierre: referencia,
} }];

// QUE SE REPORTA COMO SALIENTE: LO QUE SALIO, NO LO QUE EL MODELO DIJO.
//
// LA DEUDA QUE ESTO CIERRA (PR #97, 17/09/2026). En el Demo A y en Platinum el
// reporte del saliente cuelga de `Responder al cliente` desde que la consola
// mostro «¡Listo! Quedó agendada…» mientras el telefono habia recibido otra
// cosa (ejecucion #2867). En el Demo B seguia colgando de `Procesar
// respuesta`: la consola registraba el texto del MODELO. Con el catalogo web
// eso dejaria de ser una imprecision para ser un defecto de facturacion: en el
// turno del catalogo el texto del modelo NO es el que se envia, y el mensaje
// que Meta cobra quedaria mal registrado.
//
// POR QUE HACE FALTA ESTE NODO Y NO ALCANZA UNA EXPRESION. Este flujo no tiene
// un punto unico de salida al cliente: a `Responder al cliente` se llega desde
// cuatro lugares (la respuesta del agente, el enlace del catalogo, el comercio
// no operativo y el uso extendido). Despues del envio, `$json` es la respuesta
// de Meta -que trae el id del mensaje, pero no el texto-, asi que hay que
// averiguar CUAL de los cuatro armo lo que se envio. `isExecuted` lo dice, y
// solo esta disponible dentro de un nodo Code.
//
// NO ENVIA NADA: cuesta CERO mensajes de WhatsApp.
// PROTEGIDO, porque este nodo corre en DOS disparadores. Con el carrito del
// catálogo el mensaje entrante no existe -no lo escribió nadie por WhatsApp- y
// «Normalizar entrada» no se ejecutó: referenciarlo sin proteger tiraría la
// ejecución DESPUÉS de haber enviado un mensaje que Meta ya cobra, y el
// reporte -que es lo que la consola factura- se perdería.
let ent = {};
try { ent = $('Normalizar entrada').first().json ?? {}; } catch (e) { ent = {}; }

// EN ORDEN DE PRECEDENCIA. `Enlace del catálogo` va PRIMERO porque en el turno
// del catalogo tambien corrio `Procesar respuesta`, y lo que el cliente
// recibio es el texto armado con la direccion, no el del modelo.
// «Mensaje del carrito» va primero porque entra por el OTRO disparador: en esa
// ejecución no corrió ninguna de las demás.
const FUENTES = ['Mensaje del carrito', 'Enlace del catálogo', 'Procesar respuesta',
  'Uso extendido', 'Comercio no operativo'];

// `isExecuted` es de toda la ejecucion, no del item, y se lee PROTEGIDO: si
// una referencia fallara, el reporte tiene que salir igual. Una cifra de menos
// en la consola es malo; cortar la ejecucion despues de haber enviado el
// mensaje -que ya se pago- es peor.
const corrio = (n) => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
const itemsDe = (n) => { try { return $(n).all(); } catch (e) { return []; } };

const salidas = $input.all();
const out = [];

for (let i = 0; i < salidas.length; i++) {
  let elegido = {};
  let fuente = '';
  for (const n of FUENTES) {
    if (!corrio(n)) continue;
    const lista = itemsDe(n);
    // Emparejamiento por indice, con el ultimo como respaldo: despues de un
    // Code el emparejamiento hacia atras se rompe.
    const j = (lista[i] ?? lista[lista.length - 1] ?? { json: {} }).json ?? {};
    if (String(j.respuesta ?? '').trim() !== '') { elegido = j; fuente = n; break; }
  }

  const meta = salidas[i].json ?? {};
  out.push({ json: {
    telefono: String(elegido.from ?? ent.from ?? ''),
    texto: String(elegido.respuesta ?? ''),
    // El id que devolvio Meta: es la unica prueba de que el mensaje salio.
    idMeta: String((((meta.messages ?? [])[0]) ?? {}).id ?? ''),
    phoneNumberId: String(elegido.phoneNumberId ?? ent.phoneNumberId ?? ''),
    // Queda en la ejecucion para poder auditar de donde salio el texto.
    fuenteDelTexto: fuente,
  } });
}

return out;

// LA CONSOLA MANDA, con la misma regla que en el flujo de agendamiento: si el
// panel contesta, sus valores pisan; si no, se usan los de siempre.
//
// Este nodo se llama «Config del negocio» a proposito: es el nombre que buscan
// las expresiones que ya existen en el flujo. El Set con los valores de
// respaldo paso a llamarse «Config base».
//
// LO QUE NO SE TOCA NUNCA, Y ES LO MAS IMPORTANTE DE ESTE ARCHIVO: los rotulos
// del cobro simulado. `rotuloDemo`, `captionQr` y `textoPagoSimulado` NO se
// pisan con nada que venga de afuera, aunque el panel los mandara. Son la
// prohibicion 3 de CLAUDE.md hecha codigo: un cobro de demostracion no puede
// presentarse como real, y esa garantia no puede depender de un campo editable
// ni de que un endpoint conteste bien. Si algun dia hay cobro REAL, el flujo
// que lo haga sera otro y no llevara estos rotulos.
const base = $('Config base').first().json;

// ---------------------------------------------------------------------------
// EL 409 NO ES UN FALLO: ES LA RESPUESTA QUE CORTA EL SERVICIO.
//
// EL DEFECTO QUE ESTO ARREGLA (reportado el 2026-09-07, y confirmado en los
// TRES flujos). `configuracionFlujo` contesta 409 con `{estado, mensajeCortesia}`
// y SIN `tenantId` cuando el comercio no esta activo. La version anterior de
// este nodo exigia `tenantId` para dar la respuesta por buena, asi que un 409
// caia al respaldo... y el respaldo dice `estadoComercio: 'operativo'` escrito a
// mano. Resultado: **un comercio suspendido seguia siendo atendido**, y en el
// flujo de recordatorios seguia enviando plantillas que Meta cobra. Era
// exactamente el defecto que conectar el panel daba por cerrado, y yo lo habia
// afirmado por escrito sin comprobarlo.
//
// LA RAIZ ERA NO PODER DISTINGUIR «el panel dice que esta suspendido» de «el
// panel no contesto». Los dos se veian igual: un fallo. Ahora el nodo HTTP
// devuelve la respuesta completa -codigo y cuerpo- y aca se decide con el
// codigo:
//
//   200 + tenantId  -> configuracion del panel
//   409             -> SUSPENDIDO. Es una respuesta valida, no un error.
//   cualquier otra  -> no se pudo saber -> respaldo
//
// SOBRE `neverError`, QUE ESTE PROYECTO PROHIBIO EL 2026-09-01: aquel caso era
// un nodo que salia VERDE con un 401 y nadie miraba el resultado. Aca el codigo
// se examina explicitamente y lo que no se reconoce cae al respaldo dejando
// rastro. La regla real no es «nunca neverError», es «nunca ignores el codigo».

const respuesta = $input.first().json ?? {};
const codigo = Number(respuesta.statusCode);
const cuerpo = (respuesta.body ?? {});

const util = (v) => (typeof v === 'string' && v.trim() !== '') ? v.trim() : undefined;
const num = (v) => (typeof v === 'number' && Number.isFinite(v)) ? String(v) : undefined;
const soloLlenos = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined));

// EL NOMBRE DEL ASISTENTE lo elige cada empresa en la consola y vale para todos
// sus flujos (decidido el 15/09/2026). Es TEXTO LIBRE y va al prompt: se deja en
// una sola linea, sin corchetes ni llaves -- con ellos podria imitar un bloque
// [CONTEXTO DEL SISTEMA] -- ni comillas angulares, que el prompt usa para
// citarlo, y con el tope de 40 del servidor. Vacio = el asistente de siempre.
// La regla de identidad (asistente virtual con IA, no lo niega) NO depende de
// este campo: esta escrita en el prompt y en los textos fijos, con o sin nombre.
const nombreDelAsistente = (v) => {
  if (typeof v !== 'string') return undefined;
  const t = util(v.replace(/[\u0000-\u001f\u007f\u2028\u2029\[\]{}<>«»]/g, ' ').replace(/\s+/g, ' '));
  return t ? t.slice(0, 40).trim() : undefined;
};
// Cuantos emojis llevan los TEXTOS FIJOS, los que no pasan por el modelo. Al
// modelo se lo dice `estiloEmojis`; esto es para lo que el flujo escribe solo.
const NIVELES_EMOJIS = ['ninguno', 'pocos', 'muchos'];

// LA BIENVENIDA ES UN TEXTO FIJO: no pasa por el modelo, asi que el nombre y el
// nivel de emojis se aplican aca y no en el prompt. Sale SIEMPRE del respaldo de
// `Config base` -- el panel no la manda -- y se recalcula en los tres caminos de
// este nodo. Sin nombre y con emojis «muchos» queda EXACTAMENTE como estaba.
//   ninguno -> sin emojis;  pocos -> como mucho uno;  muchos -> como esta.
const EMOJI = /\p{Extended_Pictographic}(?:\uFE0F|\u200D\p{Extended_Pictographic})*\uFE0F?/gu;
const ajustarEmojis = (texto, nivel) => {
  if (nivel === 'ninguno') return texto.replace(EMOJI, '').replace(/ {2,}/g, ' ').replace(/^ +/, '');
  if (nivel === 'pocos') {
    let uno = false;
    return texto.replace(EMOJI, (e) => { if (uno) return ''; uno = true; return e; })
      .replace(/ {2,}/g, ' ').replace(/^ +/, '');
  }
  return texto;
};
const conPresentacion = (cfg) => {
  const nombre = util(cfg.nombreAsistente);
  let texto = String(base.textoBienvenida ?? '');
  // Funcion y no cadena de reemplazo: un `$&` dentro del nombre no se expande.
  if (nombre) texto = texto.replace(/\bSoy el asistente virtual\b/, () => `Soy ${nombre}, el asistente virtual`);
  return { ...cfg, textoBienvenida: ajustarEmojis(texto, cfg.nivelEmojis) };
};

// ---------------------------------------------------------------------------
// ESTADO DE ATENCION DEL TELEFONO: los umbrales de uso extendido
// (`Analisis/27` §5, decididos el 13/09/2026).
//
// `Traer configuracion` manda el telefono que escribio, y el panel contesta en
// `atencion` cuantas respuestas lleva ese cliente en su ventana de 24 h y que
// hacer con ESTE turno:
//   normal    -> al modelo, como siempre.
//   operador  -> paso el umbral de operador (50 por defecto): NO se llama al
//                modelo; se responde un aviso fijo y, la primera vez, se avisa
//                al negocio para que una persona tome la conversacion.
//   bloqueado -> paso el umbral de bloqueo (100 por defecto): no se envia nada
//                hasta que la ventana se renueve.
// Los umbrales los fija NovuChat por empresa en el panel. El flujo no cuenta
// nada: obedece. Quien decide es el servidor (`atencion.ts`).
//
// ANTE LA DUDA, NORMAL. Si el panel no contesta, contesta 409 o manda un
// estado que no se reconoce, el estado es `normal`: el mismo criterio de
// arriba, una caida del panel no puede dejar sin respuesta a un cliente. El
// techo de costo lo vuelve a poner el servidor en el primer turno que conteste.
// ---------------------------------------------------------------------------
const at = (codigo === 200 && cuerpo && typeof cuerpo.atencion === 'object' && cuerpo.atencion)
  ? cuerpo.atencion : {};
const atencion = {
  atencionEstado: ['normal', 'operador', 'bloqueado'].includes(at.estado) ? at.estado : 'normal',
  // El texto lo pone el panel; este es el respaldo, identico al del servidor
  // (`MENSAJE_USO_EXTENDIDO` en atencion.ts). Neutro: no habla de limites, de
  // mensajes ni de dinero, porque quien lo lee es un tercero.
  atencionMensajeFijo: util(at.mensajeFijo)
    || 'Gracias por su paciencia. Para atenderle mejor, una persona del equipo va a continuar esta conversación en breve.',
  atencionAvisarRecepcion: ['operador', 'bloqueado'].includes(at.avisarRecepcion) ? at.avisarRecepcion : '',
  atencionRespuestas: (typeof at.respuestasEnVentana === 'number' && Number.isFinite(at.respuestasEnVentana))
    ? at.respuestasEnVentana : 0,
  atencionVenceEn: util(at.ventanaVenceEn) || '',
};

if (codigo === 409) {
  return [{ json: conPresentacion({ ...base, ...atencion,
    estadoComercio: 'suspendido',
    // El texto neutro lo pone el panel: no menciona pagos ni deudas, porque el
    // cliente final no tiene por que enterarse de que el negocio debe dinero.
    mensajeComercioSuspendido: util(cuerpo.mensajeCortesia)
      || base.mensajeComercioSuspendido,
    configDeLaConsola: false,
    panelDice: 'no operativo',
  }) }];
}

const contesto = codigo === 200 && cuerpo && typeof cuerpo.tenantId === 'string';
if (!contesto) {
// Sin respuesta no se corta: una caida del panel no puede dejar sin asistente a
// todos los comercios. Un cliente escribiendo merece una respuesta.
  return [{ json: conPresentacion({ ...base, ...atencion,
    estadoComercio: base.estadoComercio ?? 'operativo',
    configDeLaConsola: false,
    panelSinRespuesta: true,
    codigoDelPanel: Number.isFinite(codigo) ? codigo : 0,
  }) }];
}

const r = cuerpo;

const dn = r.datosDelNegocio ?? {};
const op = r.operacion ?? {};
const venta = r.venta ?? {};

// --- CATALOGO POR AREA ------------------------------------------------------
// El Demo B parte el catalogo por AREA y no por precio: la carta y la tienda se
// ofrecen distinto. Un item sin precio no entra en una lista de venta -- no se
// puede cobrar lo que no tiene precio -- asi que se descarta con aviso implicito:
// simplemente no se ofrece, igual que un item dado de baja.
const items = (Array.isArray(r.catalogo) ? r.catalogo : [])
  .filter((i) => typeof i.precio === 'number');
const moneda = util(op.moneda) === 'USD' ? 'USD' : (util(base.moneda) || 'Bs');
const lista = (area) => items
  .filter((i) => String(i.area || '').toLowerCase() === area)
  .map((i) => `${i.nombre} ${i.precio} ${i.moneda === 'USD' ? 'USD' : moneda}`)
  .join(' · ');

// EL RESUMEN DEL CATALOGO llega como objeto (`resumirCatalogo`, prompt.ts) y
// al prompt va como UNA frase: el modelo lee texto, no estructuras. Solo llega
// cuando el catalogo paso el umbral de 40 items Y el catalogo web esta
// encendido; en ese caso `catalogo` viene VACIO a proposito, asi que sin esta
// frase el asistente se queda sin nada que decir de lo que vende.
const resumenDeCatalogo = (v) => {
  if (!v || typeof v !== 'object') return undefined;
  const total = (typeof v.total === 'number' && v.total > 0) ? v.total : 0;
  if (!total) return undefined;
  const areas = Array.isArray(v.areas)
    ? v.areas.filter((a) => typeof a === 'string' && a.trim() !== '') : [];
  const mon = v.moneda === 'USD' ? 'USD' : moneda;
  const partes = [total + ' productos'];
  if (areas.length) partes.push('en ' + areas.join(', '));
  if (typeof v.precioMin === 'number' && typeof v.precioMax === 'number') {
    partes.push(v.precioMin === v.precioMax
      ? ('a ' + v.precioMin + ' ' + mon)
      : ('con precios de ' + v.precioMin + ' a ' + v.precioMax + ' ' + mon));
  }
  if (v.hayACotizar === true) partes.push('y algunos a cotizar');
  return partes.join(' ') + '.';
};

const deLaConsola = soloLlenos({
  nombreNegocio: util(dn.nombreNegocio),
  horarioAtencion: util(op.horarioAtencion),
  numeroDueno: util(op.numeroRecepcion),
  phoneNumberId: util(r.phoneNumberId),
  zonaHoraria: util(op.zonaHoraria),
  menuGastronomia: lista('gastronomia') || undefined,
  catalogoRetail: lista('retail') || undefined,
  costoDelivery: num(venta.costoDelivery),
  recargoFlota: num(venta.recargoFlota),
  // Los tiempos viven en el panel como minutos y en el prompt como frase.
  tiempoCocina: typeof venta.tiempoCocinaMin === 'number'
    ? `${venta.tiempoCocinaMin} minutos` : undefined,
  // CATALOGO WEB PROPIO (`ingesta.ts`). `catalogoWeb: {activo, derivar}` sale
  // solo cuando el comercio lo encendio, y `catalogoResumen` solo cuando ademas
  // el catalogo es grande y por eso vino vacio. Sin leerlos, el asistente no
  // sabe que existe la pagina -y con un catalogo grande no sabe ni que vende-.
  // El valor por defecto es APAGADO: si el panel no contesta, no se ofrece una
  // pagina que quiza no existe.
  catalogoWebActivo: ((r.catalogoWeb ?? {}).activo === true) ? true : undefined,
  catalogoResumen: resumenDeCatalogo(r.catalogoResumen),
  // La voz sale ROTULADA del panel (`voz`), no del arreglo
  // `instruccionesDeVoz`: leerlo por posicion se rompe el dia que
  // aparezca una tercera frase.
  tratamiento: util((r.voz ?? {}).tratamiento),
  estiloEmojis: util((r.voz ?? {}).emojis),
  nombreAsistente: nombreDelAsistente((r.voz ?? {}).nombreAsistente),
  nivelEmojis: NIVELES_EMOJIS.includes((r.voz ?? {}).nivelEmojis) ? r.voz.nivelEmojis : undefined,
  // LA DIRECCION Y LO QUE FALTA. Se agrego el 2026-09-07 despues de ver al
  // asistente inventarse una: «Nuestra tienda esta ubicada en la zona central
  // de La Paz», con el campo vacio en el panel. Es EL MISMO incidente del 28 de
  // agosto en el flujo de agendamiento, que ahi ya estaba resuelto y aca no: la
  // leccion no habia cruzado de un flujo al otro.
  direccion: util(dn.direccion),
  datosQueNoTenemos: Array.isArray(dn.datosQueNoTenemos) && dn.datosQueNoTenemos.length
    ? dn.datosQueNoTenemos.join(', ') : undefined,
});

// El estado siempre sale del panel: es lo que corta el servicio.
const estadoComercio = util(r.estadoComercio) === 'activo' ? 'operativo'
  : (util(r.estadoComercio) ? 'suspendido' : (base.estadoComercio ?? 'operativo'));

return [{ json: conPresentacion({
  ...base,
  ...atencion,
  ...deLaConsola,
  estadoComercio,
  configDeLaConsola: true,
  // Se reponen DESPUES de todo, para que ninguna clave de arriba pueda pisarlos.
  rotuloDemo: base.rotuloDemo,
  captionQr: base.captionQr,
  textoPagoSimulado: base.textoPagoSimulado,
}) }];

// El comercio no esta operativo (suspendido o dado de baja).
//
// FALTABA POR COMPLETO EN ESTE FLUJO, y se descubrio el 2026-09-07 revisando el
// defecto del 409: el Demo B no tenia NINGUNA compuerta de estado, asi que
// atendia siempre, cobrara o no el negocio. El Demo A la tenia desde el
// principio; la leccion no habia cruzado, que es el mismo patron ya anotado.
//
// PROHIBIDO REVELAR EL MOTIVO: el cliente final no tiene por que enterarse de
// que el negocio debe dinero. El texto es neutro y sale de la configuracion.
//
// Se corta ANTES del agente, asi que un comercio suspendido no consume ni
// tokens ni llamadas a ninguna herramienta.
const cfg = $('Config del negocio').first().json;
const aviso = String(cfg.mensajeComercioSuspendido ?? '').trim()
  || 'En este momento no podemos atenderte por este medio. Gracias por escribirnos.';

return $input.all().map((i) => ({ json: {
  respuesta: aviso,
  comercioSuspendido: true,
  estadoComercio: cfg.estadoComercio,
  from: i.json.from,
  nombrePerfil: i.json.nombrePerfil,
  phoneNumberId: i.json.phoneNumberId,
} }));

// USO EXTENDIDO: el cliente paso el umbral de operador o el de bloqueo
// (`Analisis/27` §5). El estado lo decide el panel; ver `Config del negocio`.
//
// NO SE LLAMA AL MODELO en ninguno de los dos casos: este nodo cuelga de la
// rama falsa de `¿Atención normal?`, antes del agente. Es lo que pone techo al
// costo de una ventana: pasado el umbral de operador cada consulta cuesta un
// mensaje fijo, y pasado el de bloqueo no cuesta nada.
//
//   operador  -> se responde el aviso fijo, y se reporta como saliente: cuenta
//                y se factura como cualquier respuesta. La PRIMERA vez que se
//                entra en este estado se avisa al negocio.
//   bloqueado -> no se responde nada. La primera vez se avisa al negocio.
//
// El aviso al negocio sale por `Avisar al dueño`, que ya existe: con
// `textoAviso` manda este texto; sin el, el del pedido confirmado de siempre.
// No se crea otro envio porque un nodo de WhatsApp nuevo no recibiria la
// credencial al publicar (publicar-flujo.sh la injerta por NOMBRE de nodo).
//
// «EN SU VENTANA DE 24 HORAS» y no «hoy»: la ventana arranca con el primer
// mensaje del cliente y no coincide con el dia calendario.
const FIJO = 'Gracias por su paciencia. Para atenderle mejor, una persona del equipo va a continuar esta conversación en breve.';

// «hasta mañana» si no se sabe cuando vence; «hasta el <dia y hora>» si se sabe.
const hasta = (iso) => {
  if (!iso) return 'mañana';
  try {
    return 'el ' + new Date(iso).toLocaleString('es-BO', {
      timeZone: 'America/La_Paz', weekday: 'long', hour: '2-digit', minute: '2-digit',
    });
  } catch (e) {
    return 'el ' + iso;
  }
};

return $input.all().map((i) => {
  const j = i.json;
  const estado = j.atencionEstado === 'bloqueado' ? 'bloqueado' : 'operador';
  const avisar = j.atencionAvisarRecepcion === 'operador' || j.atencionAvisarRecepcion === 'bloqueado';
  const n = Number(j.atencionRespuestas) || 0;
  const cliente = `${j.nombrePerfil || 'sin nombre de perfil'} (${j.from})`;
  return { json: {
    from: j.from,
    nombrePerfil: j.nombrePerfil,
    phoneNumberId: j.phoneNumberId,
    numeroDueno: j.numeroDueno,
    atencionEstado: estado,
    responder: estado === 'operador',
    respuesta: estado === 'operador' ? (String(j.atencionMensajeFijo ?? '').trim() || FIJO) : '',
    avisar,
    textoAviso: estado === 'operador'
      ? `🔔 NovuChat: el cliente ${cliente} lleva ${n} respuestas del asistente en su ventana de 24 horas. ` +
        'El asistente dejó de responder con IA y le avisó que lo atiende una persona del equipo. ' +
        'Tome la conversación.'
      : `🔔 NovuChat: el cliente ${cliente} llegó a ${n} respuestas del asistente en su ventana de 24 horas. ` +
        `El asistente no le responde más hasta ${hasta(j.atencionVenceEn)}. ` +
        'Si hace falta, escríbale directamente.',
  } };
});

// EL CARRITO QUE VUELVE DE LA PAGINA: aca se decide si esta peticion se atiende.
//
// QUIEN AUTENTICA, Y QUIEN NO. La autenticacion la hace el NODO Webhook con su
// credencial de cabecera: `despertarFlujo` (catalogoWeb.ts) manda
// `Authorization: Bearer <el secreto del numero>` -el MISMO que este flujo usa
// para hablar con la ingesta- y n8n contesta 403 a lo que no lo traiga. Quien
// llega hasta este Code ya probo que conoce el secreto.
//
// LA FIRMA HMAC NO SE PUEDE VERIFICAR ACA, y conviene decirlo con todas las
// letras en vez de simular que si. `X-NovuChat-Signature` es un HMAC-SHA256
// sobre "<marca>." + cuerpo con ESE MISMO secreto; comprobarlo exigiria tener
// el secreto DENTRO del lienzo, y la prohibicion 2 de CLAUDE.md dice que un
// secreto no se escribe en un JSON de flujo. La otra via -leerlo del entorno-
// no existe: el Code de n8n corre en un vm2 con `require` cerrado
// (NODE_FUNCTION_ALLOW_BUILTIN vacio) y sin acceso al entorno. Asi que la firma
// se comprueba en FORMA y no en valor: sirve para descartar basura, no para
// autenticar. `catalogoWeb.ts` la manda igual, a proposito, para el dia que el
// flujo pueda verificarla sin romper la prohibicion 2.
//
// LO QUE SI SE COMPRUEBA, que es barato y no depende de ningun secreto:
//   - la FORMA del contrato (tipo, tenant, telefono, items, accion): un cuerpo
//     que no es un carrito no se contesta;
//   - que la marca de tiempo sea RECIENTE, lo que acota la ventana en la que
//     serviria reenviar una peticion capturada entera;
//   - que el numero de la cabecera sea un numero.
// El tenant se coteja despues, en «Mensaje del carrito», contra lo que dice el
// panel para ESE numero: son dos caminos distintos y tienen que coincidir.
const AHORA = Date.now();
// DIEZ MINUTOS, no cinco. Sin verificacion de firma el valor de esta
// comprobacion es acotado -quien pueda reenviar la peticion entera puede
// reescribir la marca-, asi que no vale la pena apretarla hasta el punto de
// tirar un carrito legitimo por un reloj corrido. Lo que si corta es el
// reenvio tardio de una captura.
const TOLERANCIA_MS = 10 * 60 * 1000;
const NUMERO = /^[0-9]{6,25}$/;
const TELEFONO = /^[0-9]{8,15}$/;
const FIRMA = /^sha256=[0-9a-f]{64}$/;
const ACCIONES = ['responder', 'plantilla_carrito_espera'];

// Texto que va a salir por WhatsApp: sin caracteres de control, con tope. Viene
// de nuestro propio servidor, pero lo que se manda a un tercero se sanea igual.
const limpio = (v, max) => String(v ?? '')
  .replace(/[\p{Cc}\p{Cf}\p{Zl}\p{Zp}]/gu, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const numero = (v) => (typeof v === 'number' && Number.isFinite(v)) ? v : 0;

const out = [];

for (const item of $input.all()) {
  const p = item.json ?? {};
  // n8n entrega las cabeceras en minusculas, pero no se confia: se normaliza.
  const cab = {};
  for (const clave of Object.keys(p.headers ?? {})) {
    cab[String(clave).toLowerCase()] = String((p.headers ?? {})[clave] ?? '');
  }
  const cuerpo = (p.body && typeof p.body === 'object') ? p.body : {};

  const num = String(cab['x-novuchat-numero'] ?? '');
  const marca = Number(cab['x-novuchat-timestamp']);
  const firma = String(cab['x-novuchat-signature'] ?? '');
  const telefono = String(cuerpo.telefono ?? '');
  const items = Array.isArray(cuerpo.items) ? cuerpo.items : [];
  const descartados = Array.isArray(cuerpo.descartados) ? cuerpo.descartados : [];

  const fallas = [];
  if (limpio(cuerpo.tipo, 20) !== 'carrito') fallas.push('tipo');
  if (!NUMERO.test(num)) fallas.push('numero');
  if (!TELEFONO.test(telefono)) fallas.push('telefono');
  if (typeof cuerpo.tenantId !== 'string' || cuerpo.tenantId.trim() === '') fallas.push('tenant');
  if (items.length === 0) fallas.push('items');
  if (!ACCIONES.includes(String(cuerpo.accion ?? ''))) fallas.push('accion');
  if (!FIRMA.test(firma)) fallas.push('firma');
  if (!Number.isFinite(marca) || Math.abs(AHORA - marca) > TOLERANCIA_MS) fallas.push('marca');

  out.push({ json: {
    procesar: fallas.length === 0,
    fallas,
    // `numero` es lo que va en la cabecera de la consulta al panel y lo que
    // `Responder al cliente` usa como remitente.
    numero: num,
    from: telefono,
    tenantId: limpio(cuerpo.tenantId, 60),
    pedidoId: limpio(cuerpo.pedidoId, 60),
    conversacionId: limpio(cuerpo.conversacionId, 80),
    accion: String(cuerpo.accion ?? ''),
    ventanaAbierta: cuerpo.ventanaAbierta === true,
    fichaCompartida: cuerpo.fichaCompartida === true,
    items: items.slice(0, 50).map((i) => ({
      nombre: limpio((i ?? {}).nombre, 80) || 'producto',
      cantidad: numero((i ?? {}).cantidad) || 1,
      subtotal: numero((i ?? {}).subtotal),
    })),
    itemsTotal: items.length,
    total: numero(cuerpo.total),
    moneda: cuerpo.moneda === 'USD' ? 'USD' : 'Bs',
    costoEnvio: numero(cuerpo.costoEnvio),
    entrega: String(cuerpo.entrega ?? '') === 'envio' ? 'envio' : 'retiro',
    // `direccion` y `nota` viajan SIEMPRE, aunque vengan vacias.
    direccion: limpio(cuerpo.direccion, 200),
    nota: limpio(cuerpo.nota, 200),
    // Solo los identificadores, que es lo unico que manda el servidor: por eso
    // el mensaje no puede nombrar lo que no entro, y pregunta.
    descartados: descartados.length,
  } });
}

return out;

// EL MENSAJE DEL CARRITO: uno solo, con todo lo que hay que decir y todo lo que
// falta preguntar.
//
// CUESTA UN MENSAJE POR CARRITO CONFIRMADO, y es el unico del catalogo web que
// agrega costo (0,0113 USD, «Base comercial» §1). Vale la pena porque
// REEMPLAZA la conversacion de toma de pedido entera -producto por producto,
// cantidad por cantidad, que son muchos mas mensajes- y porque un pedido que
// llega sin que el cliente reciba ni una palabra se siente como un pedido
// perdido. Por eso tambien va TODO junto: la confirmacion, lo que no entro, lo
// que falta y la pregunta de quien es el pedido. Dos mensajes costarian el
// doble y dirian lo mismo.
//
// LO QUE ESTE MENSAJE NO PROMETE. No dice que el pedido se esta preparando -eso
// lo decide el comercio, no el flujo-, no habla de pagos ni de cobros
// (prohibicion 3: aca no se cobro nada) y no ofrece mandar nada despues. Lo
// unico que ofrece es lo que se cumple: el pedido quedo registrado -esta en
// Firestore y el comercio lo ve en su consola- y quien quiera cambiar algo
// escribe por aca, que es lo que el asistente sabe atender.
//
// LO QUE NO PODEMOS SABER, Y POR ESO SE PREGUNTA. `descartados` trae
// IDENTIFICADORES, no nombres, y desde el webhook no se distingue si un item
// se cayo porque lo dieron de baja, porque le sacaron el precio o porque se
// agoto mientras el cliente elegia. Se dice que no entro y se pregunta cual
// era. Suponerlo seria inventar.
const previos = $('Validar carrito').all();
const entradas = $input.all();

// Comparacion sin salida temprana. Ni el tenant ni el numero son secretos -el
// unico valor que mereceria tiempo constante es la firma, y esa no se puede
// verificar en el lienzo (ver «Validar carrito»)-, pero cuesta lo mismo y no
// deja un `===` sobre un valor de autenticacion listo para copiar a donde si
// importe.
const igualSinPrisa = (a, b) => {
  const x = String(a ?? '');
  const y = String(b ?? '');
  let d = x.length === y.length ? 0 : 1;
  const n = Math.max(x.length, y.length);
  for (let i = 0; i < n; i++) d |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return d === 0;
};

// Cuantas lineas de pedido se escriben antes de resumir. Un carrito admite
// hasta 50 lineas y un mensaje de WhatsApp, 4096 caracteres: mas de una docena
// de lineas no se lee, y el total ya esta abajo.
const MAX_LINEAS = 12;
const monto = (v, moneda) => `${Number(v).toFixed(2).replace(/\.00$/, '')} ${moneda}`;

const out = [];

for (let i = 0; i < entradas.length; i++) {
  const prev = (previos[i] ?? previos[previos.length - 1] ?? { json: {} }).json ?? {};
  const rta = entradas[i].json ?? {};
  const codigo = Number(rta.statusCode);
  const cuerpo = (rta.body && typeof rta.body === 'object') ? rta.body : {};

  // MISMA DOCTRINA QUE `Config del negocio`: 200 con tenant es el panel
  // hablando; 409 es «no operativo», que es una respuesta valida; cualquier
  // otra cosa es no saber, y no saber no puede dejar sin respuesta a alguien
  // que acaba de hacer un pedido.
  const contesto = codigo === 200 && typeof cuerpo.tenantId === 'string' && cuerpo.tenantId !== '';
  const estadoComercio = contesto
    ? (cuerpo.estadoComercio === 'activo' ? 'operativo' : 'suspendido')
    : (codigo === 409 ? 'suspendido' : 'operativo');
  const at = (contesto && typeof cuerpo.atencion === 'object' && cuerpo.atencion) ? cuerpo.atencion : {};
  const atencionEstado = ['normal', 'operador', 'bloqueado'].includes(at.estado) ? at.estado : 'normal';

  let responder = true;
  let motivo = 'ok';
  if (contesto && !igualSinPrisa(cuerpo.tenantId, prev.tenantId)) {
    // El tenant del carrito lo escribio `checkoutCatalogo` desde la ficha; el
    // del panel sale del NUMERO que autentico la peticion. Son dos caminos
    // distintos: si no coinciden, este carrito no es de este comercio y no se
    // contesta. Es la regla multi-tenant, aplicada donde se puede aplicar.
    responder = false; motivo = 'el carrito no es de este comercio';
  } else if (estadoComercio !== 'operativo') {
    responder = false; motivo = 'comercio no operativo';
  } else if (atencionEstado === 'bloqueado') {
    // Pasado el umbral de bloqueo no se le manda NADA mas a ese telefono hasta
    // que la ventana se renueve (`Analisis/27` §5). Un carrito no es una
    // excepcion: el pedido igual queda en la consola.
    responder = false; motivo = 'telefono bloqueado por uso extendido';
  } else if (prev.accion !== 'responder') {
    // VENTANA DE 24 H CERRADA. Fuera de la ventana Meta solo acepta una
    // PLANTILLA aprobada, y `carrito_te_espera` NO esta aprobada (22/09/2026).
    // Mandar texto libre seria un envio que Meta rechaza, asi que no se manda
    // nada: el pedido queda en la consola, que es lo que si se cumple.
    //
    // EL DIA QUE META LA APRUEBE: colgar de «¿Avisar del carrito?» una segunda
    // compuerta por `plantillaPendiente` y un nodo de WhatsApp en modo
    // `template` con `plantilla.nombre`, `plantilla.idioma` y
    // `plantilla.parametros`, que ya salen armados de aca. OJO: Meta rechaza
    // un parametro VACIO, asi que el {{1}} de la plantilla (el nombre, que
    // este flujo no conoce) hay que resolverlo al darla de alta -o darla de
    // alta sin ese parametro-.
    responder = false; motivo = 'ventana cerrada: la plantilla carrito_te_espera no esta aprobada';
  }

  const moneda = String(prev.moneda ?? 'Bs');
  const lineas = (Array.isArray(prev.items) ? prev.items : []).slice(0, MAX_LINEAS)
    .map((it) => `• ${it.cantidad}× ${it.nombre} — ${monto(it.subtotal, moneda)}`);
  const sobran = Math.max(0, Number(prev.itemsTotal ?? 0) - lineas.length);
  if (sobran > 0) lineas.push(`• y ${sobran} producto${sobran === 1 ? '' : 's'} más`);

  // El pedido va en UN bloque -encabezado, lineas, envio y total pegados-, y
  // cada cosa distinta en el suyo. Con una linea en blanco entre cada renglon
  // el mensaje se leia como un formulario y ocupaba tres pantallas.
  const pedido = ['Recibí tu pedido del catálogo y quedó registrado:', ...lineas];
  if (Number(prev.costoEnvio ?? 0) > 0) pedido.push(`Envío: ${monto(prev.costoEnvio, moneda)}`);
  pedido.push(`Total: ${monto(prev.total, moneda)}`);
  const partes = [pedido.join('\n')];

  const entrega = [prev.entrega === 'envio'
    ? (prev.direccion
      ? `Entrega: envío a ${prev.direccion}.`
      : 'Me falta la dirección de entrega: pásamela por acá y lo cerramos.')
    : 'Entrega: pasas a recoger.'];
  if (prev.nota) entrega.push(`Tu nota: ${prev.nota}`);
  partes.push(entrega.join('\n'));

  const fuera = Number(prev.descartados ?? 0);
  if (fuera === 1) {
    partes.push('Hay 1 producto que no pude incluir. Desde acá no puedo ver si se agotó, si lo dieron '
      + 'de baja o si quedó sin precio, así que dime cuál era y lo revisamos.');
  } else if (fuera > 1) {
    partes.push(`Hay ${fuera} productos que no pude incluir. Desde acá no puedo ver si se agotaron, si `
      + 'los dieron de baja o si quedaron sin precio, así que dime cuáles eran y los revisamos.');
  }
  if (prev.fichaCompartida === true) {
    partes.push('Este enlace se puede compartir, así que confírmame que el pedido es tuyo.');
  }
  partes.push('Cualquier cambio, escríbeme por acá.');

  out.push({ json: {
    respuesta: responder ? partes.filter((t) => t !== '').join('\n\n') : '',
    responder,
    motivo,
    from: String(prev.from ?? ''),
    // El numero del panel manda sobre el de la cabecera: sale del mismo lugar
    // que valido la firma. Sin panel, el de la cabecera, que ya se autentico.
    phoneNumberId: String((contesto && cuerpo.phoneNumberId) ? cuerpo.phoneNumberId : (prev.numero ?? '')),
    pedidoId: String(prev.pedidoId ?? ''),
    tenantId: String(prev.tenantId ?? ''),
    estadoComercio,
    atencionEstado,
    panelContesto: contesto,
    // Queda armado para el dia que la plantilla exista. Hoy NO se envia.
    plantillaPendiente: prev.accion === 'plantilla_carrito_espera' && motivo.startsWith('ventana cerrada'),
    plantilla: {
      nombre: 'carrito_te_espera',
      idioma: 'es',
      parametros: ['', String(prev.itemsTotal ?? 0), monto(prev.total, moneda)],
    },
  } });
}

return out;
